customCSS:
.t, .history { color: #928374; }
.join { color: #6c782e; }
.part, .quit { color: #928374; }
.kick, .error { color: #c14a4a; }
.notice { color: #b47109; }
.action { color: #945e80; }
.mode, .nick, .topic, .server { color: #4c7a5d; }
.highlight { color: #654735; background-color: #eee0b7; border-left: 3px solid #945e80; padding-left: 8px; }
.reply { color: #928374; border-left: 2px solid #45707a; padding-left: 6px; }
.oper { color: #fbf1c7; background-color: #b47109; }
.reactions { color: #45707a; background-color: #f2e5bc; }
.card { background-color: #f2e5bc; border-color: #928374; }
.card-title { color: #45707a; }
.card-desc { color: #928374; }
.daychange { color: #928374; border-color: #f2e5bc; }
